using System;using System.IO;using System.Linq;using System.Collections.Generic;using Blacksmith;using UnityEngine;using UnityEditor;
public static class RecipeGatheringDomainChecks{
 static string D=>Path.Combine(Path.GetTempPath(),"BatterMapRecipeGatheringValidation");static List<string> passed=new(),failed=new();static void Check(bool b,string m){if(!b)throw new Exception(m);passed.Add(m);}static void Test(string name,Action run){try{run();}catch(Exception e){failed.Add(name+": "+e);}}
 static BlacksmithCatalog C=>Resources.Load<SmithingLoopContent>("SmithingLoopContent").catalog;
 static InventoryService Inv(RecipeDefinition r){var d=new SaveData{night=true,fuel=50};var v=new InventoryService(d,C);foreach(var i in r.ingredients)v.Selection.Add(new Blacksmith.Stack(i.itemId,i.count));return v;}
 public static object Run(){if(EditorApplication.isPlaying||PlayerSettings.companyName!="BatterMapValidation")throw new Exception("isolated/off");Directory.CreateDirectory(D);passed.Clear();failed.Clear();var random=UnityEngine.Random.state;
 Test("partial capacity",()=>{var g=new GameObject("QA inventory");var inv=g.AddComponent<InventorySystem>();var item=ScriptableObject.CreateInstance<ItemData>();try{item.ConfigureBridge("qa","QA","",.1f,null);inv.ConfigureCapacity(1,0);Check(inv.WorldPickupCapacity(item,30)==10,"fractional unit uses existing weight tolerance");Check(inv.TryAddWorldDrop(item,30)==10&&inv.GetItemCount(item)==10,"partial pickup commits10 of30");Check(inv.WorldPickupCapacity(item,20)==0,"full bag cannot add one");Check(!inv.TryAddItem(item,1),"ordinary add remains all-or-nothing");Check(inv.RemoveItem(item,2)&&inv.TryAddWorldDrop(item,20)==2,"released capacity permits a bounded retry");item.ConfigureBridge("qa","QA","",0,null);Check(inv.WorldPickupCapacity(item,99)==99,"zero weight bounded by offered count");}finally{UnityEngine.Object.DestroyImmediate(g);UnityEngine.Object.DestroyImmediate(item);}});
 Test("real stack splitting",()=>{var d=new SaveData();var inv=new InventoryService(d,C);var a=new Blacksmith.Stack("wood",11,Quality.Finest);d.chest.Add(a);string before=JsonUtility.ToJson(d);Check(!inv.SplitStack(d.chest,a,0)&&!inv.SplitStack(d.chest,a,11),"invalid splits do not mutate");Check(JsonUtility.ToJson(d)==before,"invalid split exact state retained");Check(inv.SplitStack(d.chest,a,4)&&a.count==7&&d.chest[1].count==4&&d.chest[1].quality==Quality.Finest,"real split preserves sum/source/quality");Check(inv.Transfer(d.chest,d.bag,d.chest[1],2)&&d.chest.Sum(x=>x.count)+d.bag.Sum(x=>x.count)==11,"split then transfer conserves quantity");});
 Test("projection references",()=>{var list=new[]{new Blacksmith.Stack("wood",2),new Blacksmith.Stack("coal",9),new Blacksmith.Stack("stone",3)};var query=new OwnedItemQuery{sort=2};var sorted=query.Apply(list,C).ToArray();Check(ReferenceEquals(sorted[0],list[1]),"quantity sort returns real stack object");query.text=C.Item("wood").displayName;Check(query.Apply(list,C).Single()==list[0],"name search keeps correct identity");query.text="";Check(query.Apply(list,C).Count()==3&&list.Sum(x=>x.count)==14,"clearing filter preserves all ownership");});
 Test("accepted attempt journal",()=>{var r=C.recipes.First(x=>x.enabled&&x.station==Station.Tools&&x.outputId=="plank");var v=Inv(r);var craft=new CraftingService(v);Check(!craft.Begin(Station.Furnace,r.tool,out _)&&v.Data.pendingExperiment==null,"rejected start creates no log");Check(craft.Begin(r.station,r.tool,out _),"authored tool attempt starts");Check(craft.Stroke(),"actual tool operation accepted");var result=craft.Finish();Check(result.success&&v.Data.experiments.Count==1&&v.Data.experiments[0].outcome=="성공","successful output creates factual journal");Check(craft.Finish()==null&&v.Data.experiments.Count==1,"repeated finish cannot duplicate log");int mastery=v.Data.progress.Single(x=>x.id==r.id).crafts;string owned=JsonUtility.ToJson(v.Data);_ = v.Data.experiments.ToArray();Check(JsonUtility.ToJson(v.Data)==owned&&mastery==1,"journal browsing never changes mastery/items");foreach(var i in r.ingredients)v.Selection.Add(new Blacksmith.Stack(i.itemId,i.count));Check(craft.Begin(r.station,r.tool,out _)&&craft.Stroke()&&craft.Finish().success,"identical second real attempt");Check(v.Data.experiments.Count==1&&v.Data.experiments[0].repetitions==2,"identical actual attempts aggregate");});
 Test("failed and cancelled attempt",()=>{var r=C.recipes.First(x=>x.enabled&&x.station==Station.Tools&&x.outputId=="plank");var v=Inv(r);var craft=new CraftingService(v);Check(craft.Begin(r.station,r.tool,out _),"failure fixture starts");var count=v.Selection.Sum(x=>x.count);Check(!craft.Finish().success&&v.Data.chest.Sum(x=>x.count)==count&&v.Data.experiments[0].outcome=="실패","actual failed work returns ingredients and logs failure");foreach(var i in r.ingredients)v.Selection.Add(new Blacksmith.Stack(i.itemId,i.count));Check(craft.Begin(r.station,r.tool,out _),"cancel fixture starts");craft.Cancel();Check(!craft.Active&&v.Selection.Count==0&&v.Data.experiments[0].outcome=="중단","explicit cancel follows return boundary");craft.Cancel();Check(v.Data.experiments.Count==2,"repeated cancel is inert");});
 Test("furnace fuel",()=>{var r=C.recipes.First(x=>x.enabled&&x.station==Station.Furnace);var v=Inv(r);var craft=new CraftingService(v);int cost=v.Selection.Sum(x=>x.count)*3;Check(craft.Begin(r.station,r.tool,out _)&&v.Data.fuel==50-cost,"authored furnace cost unchanged");craft.Cancel();Check(v.Data.fuel==50-cost&&v.Data.experiments[0].fuelSpent==cost,"cancellation never refunds furnace fuel");});
 Test("journal cap and recovery",()=>{var d=new SaveData();for(int i=0;i<205;i++){ExperimentJournal.Begin(d,Station.Tools,ToolKind.Saw,new[]{new Blacksmith.Stack("wood",1)},0);ExperimentJournal.Action(d,"actual "+i);ExperimentJournal.Complete(d,"실패",Array.Empty<Blacksmith.Stack>(),Array.Empty<Blacksmith.Stack>());}Check(d.experiments.Count==200,"journal retains latest200 distinct observed attempts");ExperimentJournal.Begin(d,Station.Tools,ToolKind.Saw,new[]{new Blacksmith.Stack("wood",1)},0);var load=JsonUtility.FromJson<SaveData>(JsonUtility.ToJson(d));ExperimentJournal.Recover(load);Check(load.pendingExperiment==null&&load.experiments[0].outcome=="미완료 · 저장된 결과 없음","saved pending attempt never invents a success/failure");var text=JsonUtility.ToJson(load);ExperimentJournal.Recover(load);Check(JsonUtility.ToJson(load)==text,"repeated recovery is idempotent");var old=JsonUtility.FromJson<SaveData>("{\"version\":1,\"day\":9,\"chest\":[{\"itemId\":\"wood\",\"count\":3,\"quality\":2}],\"progress\":[{\"id\":\"legacy\",\"crafts\":7}]}");ExperimentJournal.Recover(old);Check(old.experiments.Count==0&&old.day==9&&old.chest[0].count==3&&old.progress[0].crafts==7,"legacy save gains empty history without fabricated past");});
 Test("existing transaction regressions",()=>Check(ReleaseStabilityValidation.Run()==20,"existing20 save/crafting-capacity/fuel regressions pass"));
 UnityEngine.Random.state=random;var result=new R{passed=failed.Count==0,checks=passed.ToArray(),failures=failed.ToArray()};File.WriteAllText(D+"/domain.json",JsonUtility.ToJson(result,true));return result;}
 [Serializable]class R{public bool passed;public string[] checks,failures;}
}
